"use client";

import Link from "next/link";
import { useRouter, useSearchParams } from "next/navigation";
import { Suspense, useEffect, useRef, useState } from "react";
import { flushSync } from "react-dom";
import type { CatalogResponse, Customer, Inquiry, Order, PaymentMethod, Product, Review } from "@/lib/types";
import { categories, fulfillmentLabels, money, paymentLabels } from "@/lib/types";
import { Icon } from "./icons";
import Admin from "./admin";
import Payment from "./payment";

type Line = { variantId: string; quantity: number };
const CART = "nuri-market-cart";
const WISH = "nuri-market-wishlist";
const ACCESS = "nuri-market-order-access";
export function readLocal<T>(key: string, fallback: T): T {
  try { return JSON.parse(localStorage.getItem(key) ?? "null") ?? fallback; } catch { return fallback; }
}
export async function request<T>(url: string, body?: unknown, token?: string): Promise<T> {
  const response = await fetch(url, { method: body === undefined ? "GET" : "POST", headers: { "Content-Type": "application/json", ...(token ? { "x-order-access": token } : {}) }, ...(body !== undefined ? { body: JSON.stringify(body) } : {}) });
  const data = await response.json();
  if (!response.ok) throw new Error(data.error ?? "요청을 처리하지 못했습니다. 다시 시도해 주세요.");
  return data;
}
// Fade the live content, not a resized snapshot: text keeps its rendered size.
function changeView(update: () => void, selector: string) {
  flushSync(update);
  const target = document.querySelector(selector);
  if (!target || matchMedia("(prefers-reduced-motion: reduce)").matches || document.documentElement.dataset.marketInput === "keyboard") return;
  target.getAnimations().forEach(animation => animation.cancel());
  target.animate([{ opacity: .65 }, { opacity: 1 }], { duration: 160, easing: "cubic-bezier(0.23, 1, 0.32, 1)" });
}
function stockOf(product: Product) { return product.variants.reduce((sum, variant) => sum + Math.max(0, variant.stock), 0); }
function isOpen(product: Product) { return !product.dropAt || new Date(product.dropAt).getTime() <= Date.now(); }

export function Modal({ title, children, onClose, sheet = false, wide = false }: { title: string; children: React.ReactNode; onClose: () => void; sheet?: boolean; wide?: boolean }) {
  const ref = useRef<HTMLDialogElement>(null);
  useEffect(() => { const dialog = ref.current; dialog?.showModal(); return () => { dialog?.close(); }; }, []);
  return <dialog ref={ref} className={`modal${sheet ? " sheet" : ""}${wide ? " modal-wide" : ""}`} onCancel={onClose} onClick={event => { if (event.target === event.currentTarget) onClose(); }}><div className="modal-inner"><div className="modal-heading"><h2>{title}</h2><button className="icon-button" onClick={onClose} aria-label="창 닫기"><Icon name="close" /></button></div>{children}</div></dialog>;
}

export default function Market({ path }: { path: string[] }) {
  const router = useRouter();
  const [catalog, setCatalog] = useState<CatalogResponse | null>(null);
  const [error, setError] = useState("");
  const [cart, setCart] = useState<Line[]>([]);
  const [wishes, setWishes] = useState<string[]>([]);
  const [notice, setNotice] = useState("");
  const [sheet, setSheet] = useState<{ product: Product; buy: boolean } | null>(null);
  const [guide, setGuide] = useState<Product | null>(null);
  const [hydrated, setHydrated] = useState(false);
  const section = path[0] ?? "home";
  const mainRef = useRef<HTMLElement>(null);
  const routeKey = path.join("/");
  useEffect(() => {
    const main = mainRef.current;
    if (!main || !catalog || document.documentElement.dataset.marketInput === "keyboard" || matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    const animation = main.animate([{opacity:.65},{opacity:1}], {duration:220,easing:"cubic-bezier(0.23, 1, 0.32, 1)"});
    return () => animation.cancel();
  }, [routeKey, Boolean(catalog)]);
  async function load() { try { setCatalog(await request<CatalogResponse>("/api/catalog")); setError(""); } catch (e) { setError((e as Error).message); } }
  useEffect(() => { void load(); setCart(readLocal(CART, [])); setWishes(readLocal(WISH, [])); setHydrated(true); }, []);
  useEffect(() => { if (hydrated) localStorage.setItem(CART, JSON.stringify(cart)); }, [cart, hydrated]);
  useEffect(() => { if (hydrated) localStorage.setItem(WISH, JSON.stringify(wishes)); }, [wishes, hydrated]);
  useEffect(() => { if (!notice) return; const timeout = setTimeout(() => setNotice(""), 3200); return () => clearTimeout(timeout); }, [notice]);
  function wish(id: string) { setWishes(previous => previous.includes(id) ? previous.filter(item => item !== id) : [...previous, id]); }
  function add(line: Line, buy: boolean) {
    if (buy) { localStorage.setItem("nuri-market-checkout", JSON.stringify([line])); router.push("/checkout"); }
    else { setCart(previous => { const existing = previous.find(item => item.variantId === line.variantId); const variant = catalog?.products.flatMap(product => product.variants).find(item => item.id === line.variantId); return existing ? previous.map(item => item.variantId === line.variantId ? { ...item, quantity: Math.min(10, item.quantity + line.quantity, variant?.stock ?? line.quantity) } : item) : [...previous, line]; }); setNotice("장바구니에 담았습니다."); }
    setSheet(null);
  }
  if (section === "admin") return <Admin />;
  if (error && !catalog) return <div className="market-shell"><main className="load-state"><h1>NURI MARKET</h1><p className="error-text">{error}</p><button className="primary" onClick={load}>다시 불러오기</button></main></div>;
  if (!catalog) return <div className="market-shell"><main className="load-state"><div className="wordmark"><img src="/brand/nuri-market-light.svg" alt="NURI MARKET" width="7906" height="1120"/></div><p>작은 취향을 모으는 중</p><div className="loading-line" /></main></div>;
  const product = section === "product" ? catalog.products.find(item => item.slug === path[1]) : undefined;
  const cartCount = cart.reduce((sum, line) => sum + line.quantity, 0);
  const onProduct = Boolean(product);
  return <div className="market-shell" onKeyDownCapture={() => { document.documentElement.dataset.marketInput = "keyboard"; }} onPointerDownCapture={() => { document.documentElement.dataset.marketInput = "pointer"; }}>
    <a className="skip-link" href="#main-content">본문으로 바로가기</a>
    <div className="preview-strip">{catalog.mode === "preview" ? "샘플 컬렉션 · 체험 주문만 가능합니다" : catalog.mode === "test" ? "결제 테스트 운영 · 실제 판매 전 점검 중" : "NURI MARKET 공식 스토어"}</div>
    <header className="header"><div className="header-inner"><Link href="/" className="wordmark" aria-label="NURI MARKET 홈"><img src="/brand/nuri-market-light.svg" alt="NURI MARKET" width="7906" height="1120"/></Link><nav className="desktop-links" aria-label="주요 메뉴"><Link href="/search" aria-current={section === "search" ? "page" : undefined}>모든 상품</Link><Link href="/search?category=clicker">클릭커</Link><Link href="/search?category=apparel">의류·모자</Link><Link href="/search?category=figure">작은 오브제</Link></nav><div className="header-actions"><Link className="icon-button" href="/search" aria-label="상품 검색"><Icon name="search" /></Link><Link className="icon-button desktop-only" href="/wishlist" aria-label="관심 상품"><Icon name="heart" /></Link><Link className="icon-button" href="/cart" aria-label={`장바구니 ${cartCount}개`}><Icon name="bag" />{cartCount > 0 && <span className="count-badge">{cartCount}</span>}</Link><Link href="/my" className="desktop-only account-link">마이</Link><Link href="/nurimarket/login" className="account-link">로그인</Link></div></div></header>
    {(section === "home" || section === "search") && <Suspense fallback={<CategoryLinks active={section === "home" ? "all" : ""} />}><CategoryNavigation section={section} /></Suspense>}
    <main ref={mainRef} id="main-content" data-route={routeKey || "home"} className={`main ${onProduct ? "product-main" : ""}`}>
      {section === "home" && <Home catalog={catalog} wishes={wishes} wish={wish} />}
      {section === "search" && <Suspense fallback={<p>상품을 불러오는 중</p>}><Search catalog={catalog} wishes={wishes} wish={wish} /></Suspense>}
      {section === "wishlist" && <><PageTitle title="관심 상품" subtitle="마음에 드는 작은 취향을 모아 두세요."/><ProductGrid products={catalog.products.filter(item => wishes.includes(item.id))} wishes={wishes} wish={wish} shipping={catalog.settings.shipping} empty="아직 모아 둔 상품이 없습니다."/></>}
      {section === "product" && (product ? <ProductDetail key={product.id} product={product} catalog={catalog} wished={wishes.includes(product.id)} wish={() => wish(product.id)} open={buy => setSheet({ product, buy })} guide={() => setGuide(product)} /> : <Empty title="상품을 찾을 수 없습니다." />)}
      {section === "cart" && <Cart catalog={catalog} cart={cart} setCart={setCart} checkout={() => { localStorage.setItem("nuri-market-checkout", JSON.stringify(cart)); router.push("/checkout"); }} />}
      {section === "checkout" && <Checkout catalog={catalog} fallback={cart} onCreated={() => void load()} />}
      {section === "my" && <My />}
      {section === "order" && <OrderView id={path[1]} />}
      {section === "payment" && <Payment result={path[1]} />}
      {section === "policy" && <Policy kind={path[1]} catalog={catalog} />}
      {!["home","search","wishlist","product","cart","checkout","my","order","payment","policy"].includes(section) && <Empty title="페이지를 찾을 수 없습니다." />}
    </main>
    <Footer catalog={catalog} />
    {!onProduct && section !== "checkout" && <nav className="bottom-nav" aria-label="모바일 주요 메뉴">{[{href:"/",name:"home",label:"홈",key:"home"},{href:"/search",name:"search",label:"검색",key:"search"},{href:"/wishlist",name:"heart",label:"찜",key:"wishlist"},{href:"/my",name:"user",label:"마이",key:"my"}].map(item => <Link key={item.key} href={item.href} className={section === item.key ? "active" : ""} aria-current={section === item.key ? "page" : undefined}><Icon name={item.name} /><span>{item.label}</span></Link>)}</nav>}
    {notice && <div className="toast" role="status"><Icon name="check" size={18}/>{notice}<Link href="/cart">보기</Link></div>}
    {sheet && <OptionSheet product={sheet.product} buy={sheet.buy} onClose={() => setSheet(null)} onAdd={line => add(line, sheet.buy)} />}
    {guide && <Modal title="실측·소재 안내" onClose={() => setGuide(null)}><p className="muted">현재 콘셉트 상품입니다. 실제 실측표와 촬영 이미지는 상품 검수 후 등록합니다.</p><SpecTable product={guide}/><p className="hint">모자: 깊이·챙 길이·둘레 범위 / 의류: 가슴·어깨·소매·총장과 측정 오차를 함께 안내합니다.</p></Modal>}
  </div>;
}

function CategoryLinks({ active }: { active: string }) {
  return <nav className="category-strip" aria-label="상품 분류"><div>{categories.map(category => <Link key={category.id} href={category.id === "all" ? "/search" : `/search?category=${category.id}`} className={active === category.id ? "active" : ""} aria-current={active === category.id ? "page" : undefined}>{category.label}</Link>)}</div></nav>;
}
function CategoryNavigation({ section }: { section: string }) {
  const params = useSearchParams();
  return <CategoryLinks active={section === "home" ? "all" : params.get("category") ?? "all"} />;
}
function PageTitle({ title, subtitle }: { title: string; subtitle?: string }) { return <div className="page-title"><h1>{title}</h1>{subtitle && <p>{subtitle}</p>}</div>; }
function Empty({ title }: { title: string }) { return <div className="empty"><Icon name="box" size={38}/><h2>{title}</h2><Link href="/search" className="primary">상품 둘러보기</Link></div>; }
function ProductGrid({ products, wishes, wish, empty, shipping }: { products: Product[]; wishes: string[]; wish: (id: string) => void; empty?: string; shipping: CatalogResponse["settings"]["shipping"] }) { return products.length ? <div className="product-grid">{products.map(product => <ProductCard key={product.id} product={product} wished={wishes.includes(product.id)} wish={() => wish(product.id)} shipping={shipping}/>)}</div> : <Empty title={empty ?? "조건에 맞는 상품이 없습니다."}/>; }
function ProductCard({ product, wished, wish, shipping }: { product: Product; wished: boolean; wish: () => void; shipping: CatalogResponse["settings"]["shipping"] }) {
  const stock = stockOf(product);
  return <article className="product-card"><div className="product-visual"><Link href={`/product/${product.slug}`} tabIndex={-1}><img src={product.images[0]} alt={product.sample ? `${product.name} 콘셉트 이미지` : product.name} loading="lazy" width="600" height="600" /></Link><button className={`wish-button ${wished ? "is-wished" : ""}`} aria-label={`${product.name} ${wished ? "찜 해제" : "찜하기"}`} aria-pressed={wished} onClick={wish}><Icon name="heart" size={21}/></button>{!stock && <span className="soldout">품절</span>}</div><div className="product-copy"><span className="line-name">{product.line}</span><h3><Link href={`/product/${product.slug}`}>{product.name}</Link></h3><strong>{money(product.price)}</strong><p className="card-shipping">배송 {money(shipping.fee)} · {money(shipping.freeThreshold)} 이상 무료</p><div className="product-tags">{product.sample && <span>샘플</span>}{!isOpen(product) && <span>공개 예정</span>}{stock > 0 && stock <= 5 && <span className="blue">소량 남음</span>}</div></div></article>;
}
function Reveal({children}:{children:React.ReactNode}) {
  const ref=useRef<HTMLDivElement>(null);
  useEffect(()=>{const element=ref.current;if(!element||matchMedia("(prefers-reduced-motion: reduce)").matches)return;
    const observer=new IntersectionObserver(entries=>{if(entries[0].isIntersecting){element.animate([{opacity:0,transform:"translateY(8px)"},{opacity:1,transform:"translateY(0)"}],{duration:280,easing:"cubic-bezier(0.23, 1, 0.32, 1)"});observer.disconnect();}},{threshold:0.08});observer.observe(element);return()=>observer.disconnect();},[]);
  return <div ref={ref}>{children}</div>;
}
function Home({ catalog, wishes, wish }: { catalog: CatalogResponse; wishes: string[]; wish: (id: string) => void }) {
  const [slide,setSlide]=useState(0),[category,setCategory]=useState("all");
  const gesture=useRef<{id:number;x:number;y:number;horizontal:boolean}|null>(null);
  const suppressClick=useRef(false);
  const campaigns=[{eyebrow:"SMALL THINGS, GOOD DAYS",title:<>손안에 담는<br/>좋아하는 것들.</>,description:"기분 좋은 한 번의 클릭, 내 곁의 작은 오브제.",link:"손끝의 즐거움 발견하기",href:"/search?category=clicker"},{eyebrow:"FROM THE TABLE, TO EVERYDAY",title:<>테이블 밖에서도,<br/>나답게.</>,description:"가볍게 쓰고, 편하게 입는 테이블 클럽.",link:"테이블 클럽 둘러보기",href:"/search?category=apparel"}];
  const collection=[...catalog.products].sort((a,b)=>Number(stockOf(b)>0)-Number(stockOf(a)>0)||["clicker","figure","apparel","gear"].indexOf(a.category)-["clicker","figure","apparel","gear"].indexOf(b.category));
  return <>
    <section className={`hero hero-campaign hero-campaign-${slide}`} aria-roledescription="캐러셀" aria-label="NURI 샘플 컬렉션"
      onPointerDown={event=>{
        suppressClick.current=false;
        if (!event.isPrimary) { gesture.current=null; return; }
        if (event.pointerType==="mouse" || (event.target as Element).closest("button")) return;
        gesture.current={id:event.pointerId,x:event.clientX,y:event.clientY,horizontal:false};
      }}
      onPointerMove={event=>{
        const start=gesture.current;
        if (!start || start.id!==event.pointerId) return;
        const dx=event.clientX-start.x,dy=event.clientY-start.y;
        if (!start.horizontal) {
          if (Math.max(Math.abs(dx),Math.abs(dy))<10) return;
          if (Math.abs(dy)>=Math.abs(dx)) { gesture.current=null; return; }
          start.horizontal=true;
          suppressClick.current=true;
          event.currentTarget.setPointerCapture(event.pointerId);
        }
      }}
      onPointerUp={event=>{
        const start=gesture.current;
        gesture.current=null;
        if (!start || start.id!==event.pointerId || !start.horizontal) return;
        const dx=event.clientX-start.x;
        if (Math.abs(dx)>=40) setSlide(previous=>(previous+(dx<0?1:-1)+campaigns.length)%campaigns.length);
      }}
      onPointerCancel={()=>{gesture.current=null;}}
      onClickCapture={event=>{if (suppressClick.current && event.detail>0) {event.preventDefault();event.stopPropagation();suppressClick.current=false;}}}>
      {campaigns.map((campaign,index) => <div key={campaign.eyebrow} className={`hero-frame${slide===index ? " is-active" : ""}`} aria-hidden={slide!==index} inert={slide!==index}>
        {index===0 ? <picture><source media="(max-width:760px)" srcSet="/hero-mobile.webp"/><img src="/hero.webp" width="1280" height="650" alt="푸른 클릭커와 작은 초록 오브제의 콘셉트 컬렉션" fetchPriority="high"/></picture> : <img className="campaign-cap" src="/products/cap.webp" width="600" height="600" alt="차콜 테이블 클럽 볼캡 콘셉트 이미지"/>}
        <div className="hero-copy"><p className="eyebrow">{campaign.eyebrow}</p><h1>{campaign.title}</h1><span>{campaign.description}</span><Link href={campaign.href} className="hero-link">{campaign.link}<span><Icon name="arrow" size={17}/></span></Link></div>
      </div>)}
      <div className="hero-controls"><span>샘플 컬렉션 · 제작 방향 미리보기</span><div aria-label="배너 선택">{campaigns.map((campaign,index)=><button key={campaign.eyebrow} aria-label={`${index+1}번 배너: ${index===0?"클릭커와 작은 오브제":"테이블 클럽"}`} aria-pressed={slide===index} onClick={()=>setSlide(index)}><i/></button>)}<span aria-live="polite">0{slide+1} / 02</span></div></div>
    </section>
    <div className="discovery-shortcuts">{[{id:"clicker",label:"기분 좋은 한 번의 클릭",sub:"클릭커",image:"clicker",number:"01"},{id:"figure",label:"작지만 확실한 존재감",sub:"미니 피규어",image:"figure",number:"02"},{id:"apparel",label:"오늘도 편하게, 나답게",sub:"의류·모자",image:"cap",number:"03"},{id:"gear",label:"테이블 위의 작은 차이",sub:"홀덤 굿즈",image:"gear",number:"04"}].map(item => <Link key={item.id} href={`/search?category=${item.id}`}><div><img src={`/products/${item.image}.webp`} width="120" height="120" alt="" loading="lazy"/></div><div className="shortcut-copy"><span>{item.number} / EXPLORE</span><strong>{item.sub}</strong><p>{item.label}</p></div><Icon name="arrow" size={16}/></Link>)}</div>
    <section className="catalog-section"><div className="section-heading"><div><span className="eyebrow">THE NURI EDIT</span><h2>오늘의 작은 발견<span>.</span></h2><p>좋아하는 마음으로 고른, 누리의 컬렉션.</p></div><Link href="/search">전체 상품<Icon name="arrow" size={16}/></Link></div>
      <div className="collection-controls"><div className="collection-tabs" aria-label="홈 컬렉션 분류">{categories.map(item=><button key={item.id} aria-pressed={category===item.id} onClick={()=>changeView(()=>setCategory(item.id), ".product-grid")} className={category===item.id?"active":""}>{item.label}</button>)}</div><span>{catalog.products.filter(item=>category==="all"||item.category===category).length} ITEMS</span></div>
      <ProductGrid products={collection.filter(item=>category==="all"||item.category===category)} wishes={wishes} wish={wish} shipping={catalog.settings.shipping}/>
    </section>
    <Reveal><section className="editorial-pair" aria-label="컬렉션 이야기"><Link href="/search?category=clicker" className="editorial-card editorial-blue"><div className="editorial-copy"><span className="eyebrow">01 / JUST ONE CLICK</span><h2>손이 가는 즐거움.</h2><p>잠깐의 쉼에도, 생각을 고를 때에도.</p><span className="editorial-link">클릭커 컬렉션<Icon name="arrow" size={16}/></span></div><img src="/products/orbit.webp" alt="오빗 클릭커 콘셉트 이미지" width="600" height="600" loading="lazy"/></Link><Link href="/search?category=figure" className="editorial-card editorial-mint"><div className="editorial-copy"><span className="eyebrow">02 / YOUR LITTLE COMPANY</span><h2>곁에 두고 싶은 마음.</h2><p>책상 한 켠, 나만 아는 작은 세계.</p><span className="editorial-link">작은 오브제 만나기<Icon name="arrow" size={16}/></span></div><img src="/products/figure.webp" alt="리틀 오빗 미니 피규어 콘셉트 이미지" width="600" height="600" loading="lazy"/></Link></section></Reveal>
    <Reveal><section className="table-story"><div className="table-story-visual"><img src="/products/tee.webp" alt="테이블 클럽 차콜 티셔츠 콘셉트 이미지" width="600" height="600" loading="lazy"/><span>TABLE CLUB / CONCEPT</span></div><div className="table-story-copy"><span className="eyebrow">A LITTLE MORE YOU</span><h2>좋아하는 걸 입는<br/>가장 편한 방법.</h2><p>테이블에서 시작된 취향이 일상이 되도록.<br/>담백한 실루엣과 작은 디테일을 담았습니다.</p><Link href="/search?category=apparel" className="hero-link">테이블 클럽 만나보기<span><Icon name="arrow" size={17}/></span></Link></div></section></Reveal>
    <section className="brand-note"><div><span className="eyebrow">NURI MARKET</span><h2>작은 취향이 모여,<br/>나의 일상이 되니까.</h2><p>놀고, 입고, 곁에 두고. 누리에서 만나요.</p><span>현재 공개된 상품은 제작 방향을 보여주는 샘플입니다.</span></div><div className="brand-note-symbol" aria-hidden="true">n.</div></section>
  </>;
}
function Search({ catalog, wishes, wish }: { catalog: CatalogResponse; wishes: string[]; wish: (id: string) => void }) {
  const [query, setQuery] = useState(""); const [category, setCategory] = useState("all"); const [sort, setSort] = useState("latest"); const [available, setAvailable] = useState(false);
  const params = useSearchParams();
  useEffect(() => { setCategory(params.get("category") ?? "all"); }, [params]);
  const products = catalog.products.filter(product => (category === "all" || product.category === category) && `${product.name} ${product.line}`.toLocaleLowerCase().includes(query.trim().toLocaleLowerCase()) && (!available || stockOf(product) > 0)).sort((a,b) => sort === "low" ? a.price-b.price : sort === "high" ? b.price-a.price : 0);
  return <><PageTitle title="취향을 찾아보세요"/><form className="search-form" onSubmit={e => e.preventDefault()}><Icon name="search"/><input aria-label="상품 이름 검색" placeholder="클릭커, 모자, 작은 오브제" value={query} onChange={e => setQuery(e.target.value)}/>{query && <button type="button" className="icon-button" aria-label="검색어 지우기" onClick={() => setQuery("")}><Icon name="close" size={18}/></button>}</form><div className="filter-chips">{categories.map(item => <button key={item.id} className={category === item.id ? "active" : ""} onClick={() => { changeView(()=>setCategory(item.id), ".product-grid"); window.history.replaceState(null,"",item.id === "all" ? "/search" : `/search?category=${item.id}`); }} aria-pressed={category === item.id}>{item.label}</button>)}</div><div className="list-controls"><span>{products.length}개 상품</span><div><label className="check-label"><input type="checkbox" checked={available} onChange={e => setAvailable(e.target.checked)}/>재고 있음</label><select aria-label="상품 정렬" value={sort} onChange={e => setSort(e.target.value)}><option value="latest">등록순</option><option value="low">낮은 가격순</option><option value="high">높은 가격순</option></select></div></div><ProductGrid products={products} wishes={wishes} wish={wish} shipping={catalog.settings.shipping}/></>;
}

function SpecTable({ product }: { product: Product }) { return <dl className="spec-table">{product.specs.map(spec => <div key={spec.label}><dt>{spec.label}</dt><dd>{spec.value}</dd></div>)}</dl>; }
function ProductDetail({ product, catalog, wished, wish, open, guide }: { product: Product; catalog: CatalogResponse; wished: boolean; wish: () => void; open: (buy: boolean) => void; guide: () => void }) {
  const [image, setImage] = useState(0); const [tab, setTab] = useState("info"); const [audioError, setAudioError] = useState("");
  const [playing,setPlaying] = useState(false);
  const audioRef = useRef<HTMLAudioElement|null>(null);
  useEffect(()=>{
    setPlaying(false);setAudioError("");
    if(!product.soundUrl)return;
    const audio=new Audio(product.soundUrl);audio.preload="none";audioRef.current=audio;
    audio.onended=()=>setPlaying(false);
    audio.onerror=()=>{setPlaying(false);setAudioError("오디오를 불러오지 못했습니다. 다시 시도해 주세요.");};
    return ()=>{audio.onended=null;audio.onerror=null;audio.pause();audio.currentTime=0;audio.removeAttribute("src");audio.load();audioRef.current=null;};
  },[product.soundUrl]);
  function toggleSound(){const audio=audioRef.current;if(!audio)return;setAudioError("");if(!audio.paused){audio.pause();audio.currentTime=0;setPlaying(false);return;}audio.pause();audio.currentTime=0;setPlaying(true);void audio.play().catch(error=>{if((error as DOMException).name==="AbortError")return;if(audioRef.current===audio){setPlaying(false);setAudioError("오디오를 재생하지 못했습니다. 다시 시도해 주세요.");}});}
  const stock = stockOf(product); const openSale = isOpen(product); const reviews = (catalog.publicReviews??[]).filter(review=>review.productId===product.id);
  return <><div className="breadcrumb"><Link href="/search">모든 상품</Link><Icon name="arrow" size={13}/><span>{categories.find(category => category.id === product.category)?.label}</span></div><div className="pdp-top"><div><div className="pdp-image"><img src={product.images[image]} alt={product.sample ? `${product.name} 콘셉트 이미지 ${image+1}` : product.name} width="600" height="600"/><span>{image+1} / {product.images.length}</span></div>{product.images.length > 1 && <div className="image-thumbs">{product.images.map((src,index) => <button key={src} onClick={() => changeView(()=>setImage(index), ".pdp-image")} aria-label={`${index+1}번 이미지 보기`} aria-pressed={image === index}><img src={src} alt="" width="72" height="72"/></button>)}</div>}</div><div className="pdp-info"><span className="line-name">{product.line}</span><h1>{product.name}</h1><p className="pdp-description">{product.description}</p><strong className="pdp-price">{money(product.price)}</strong>{product.sample && <div className="sample-note"><Icon name="box" size={18}/><div><strong>제작 중인 샘플 컬렉션</strong><p>콘셉트 이미지와 체험 가격입니다. 실제 상품 정보는 출시 전 확정합니다.</p></div></div>}<dl className="buy-facts"><div><dt>배송비</dt><dd>{money(catalog.settings.shipping.fee)}<small>{money(catalog.settings.shipping.freeThreshold)} 이상 무료</small></dd></div><div><dt>출고 안내</dt><dd>{catalog.settings.shippingReady ? catalog.settings.shipping.cutoff : "실제 출고 일정 확정 전"}</dd></div><div><dt>상품 상태</dt><dd>{!openSale ? `공개 예정 ${new Date(product.dropAt!).toLocaleString("ko-KR")}` : stock ? `${product.sample ? "체험 " : ""}옵션 선택 가능` : "품절"}</dd></div></dl>{product.category === "clicker" && <div className={`sound-panel${playing?" is-playing":""}`}><button onClick={toggleSound} disabled={!product.soundUrl} aria-pressed={playing}><span className="sound-icon"><Icon name="sound" size={20}/><span className="sound-bars" aria-hidden="true"><i/><i/><i/><i/></span></span>{playing?"소리 멈추기":product.soundUrl?(product.sample?"샘플 클릭 소리 듣기":"실제 클릭 소리 듣기"):"클릭 소리 준비 중"}</button><p>{audioError || (product.soundUrl?(product.sample?"기능 체험용 합성 소리이며 실제 상품을 녹음한 소리가 아닙니다.":"실제 상품의 녹음입니다. 재생 환경에 따라 실제 소리와 차이가 있을 수 있습니다."):"스위치별 실제 녹음을 준비하고 있습니다.")}</p><ClickerMetrics product={product}/></div>}{product.category === "figure" && <p className="hint">실측 비교 사진은 상품 출시 전에 두 번째 이미지에 등록합니다. 화면상의 크기는 실제 크기와 다릅니다.</p>}{product.category === "apparel" && <button className="text-button" onClick={guide}>실측·소재 안내 <Icon name="arrow" size={15}/></button>}<div className="desktop-buy"><button className={`secondary ${wished ? "is-wished" : ""}`} onClick={wish} aria-label={wished ? "찜 해제" : "찜하기"} aria-pressed={wished}><Icon name="heart"/></button><button className="secondary" disabled={!stock || !openSale} onClick={() => open(false)}>장바구니</button><button className="primary" disabled={!stock || !openSale} onClick={() => open(true)}>{stock ? "바로 구매" : "품절"}</button></div><p className="payment-note">카드 · 네이버페이 · 카카오페이 · 가상계좌{catalog.mode === "preview" ? " / 연동 전 체험 주문" : " / 제공 수단은 결제창에서 확인"}</p></div></div><nav className="pdp-tabs" aria-label="상품 상세 영역">{[{id:"info",label:"상품정보"},{id:"reviews",label:"리뷰"},{id:"qa",label:"Q&A"},{id:"shipping",label:"배송·교환"}].map(item => <button key={item.id} onClick={() => changeView(()=>setTab(item.id), ".pdp-content")} className={tab === item.id ? "active" : ""} aria-pressed={tab === item.id}>{item.label}</button>)}</nav><section className="pdp-content">{tab === "info" && <><h2>작지만, 분명한 취향.</h2><p>{product.description}</p><SpecTable product={product}/><details open><summary>사용 연령·안전 안내</summary><p>대상 연령: {product.safety.age || "확정 전"}<br/>안전확인: {product.safety.certification === "verified" ? "검증 완료" : product.safety.certification === "not_required" ? "비대상 검토" : "확인 진행 중"}</p>{product.safety.certificateNumber && <p>인증번호: {product.safety.certificateNumber}</p>}<p>작은 부품이 포함된 상품은 삼킴 위험이 있습니다. 어린이용 판매 여부와 제품의 분류·시험·표시 요건을 출시 전에 검토합니다.</p></details><details><summary>소재와 마감 안내</summary><p>실제 소재·도색 방식·마감 편차 안내를 등록할 예정입니다. 개별 상품의 하자 및 청약철회 권리는 별도로 적용됩니다.</p></details></>}{tab === "reviews" && <><h2>상품 리뷰 {reviews.length>0&&<small>{reviews.length}개</small>}</h2>{reviews.length?reviews.map(review=><article className="public-review" key={review.id}><div><strong>{review.rating} / 5점</strong><time dateTime={review.createdAt}>{new Date(review.createdAt).toLocaleDateString("ko-KR")}</time></div><p>{review.content}</p></article>):<p className="muted">아직 공개된 리뷰가 없습니다. 주문 조회 화면에서 구매한 상품의 리뷰를 작성할 수 있습니다.</p>}</>}{tab === "qa" && <><h2>상품 문의</h2><p className="muted">주문 관련 문의는 주문 조회 화면에서 남겨 주세요. 상품 문의는 고객센터로 연결합니다.</p><Link href="/my" className="secondary inline-button">주문 조회</Link>{catalog.settings.seller.email && <a href={`mailto:${catalog.settings.seller.email}`} className="text-button">이메일 문의</a>}</>}{tab === "shipping" && <><h2>배송·교환·반품 안내</h2><p>배송비 {money(catalog.settings.shipping.fee)} / {money(catalog.settings.shipping.freeThreshold)} 이상 무료</p><p>일반적으로 상품을 공급받은 날부터 7일 이내 청약철회가 가능합니다. 표시·광고 또는 계약과 다른 상품에는 별도 청약철회 기간이 적용되며 구매확정 후에도 해당 요청을 접수합니다.</p><Link href="/policy/shipping" className="text-button">배송·교환 정책 전체 보기 <Icon name="arrow" size={16}/></Link></>}</section><div className="sticky-buy"><button className={`icon-button ${wished ? "is-wished" : ""}`} onClick={wish} aria-label={wished ? "찜 해제" : "찜하기"} aria-pressed={wished}><Icon name="heart"/></button><button className="secondary" disabled={!stock || !openSale} onClick={() => open(false)}>장바구니</button><button className="primary" disabled={!stock || !openSale} onClick={() => open(true)}>{stock ? "바로 구매" : "품절"}</button></div></>;
}

function ClickerMetrics({product}:{product:Product}) {
  const pressure = product.sample ? null : product.specs.find(spec=>/키압|작동\s*하중|압력/.test(spec.label));
  const pressureMatch = pressure?.value.match(/^\s*(\d+(?:\.\d+)?)\s*(?:g|gf)(?:\s|\(|$)/i);
  const pressureValue = pressureMatch ? Number(pressureMatch[1]) : null;
  const noise = product.sample ? null : product.specs.find(spec=>/소음/.test(spec.label));
  const noiseDb = noise?.value.match(/^\s*(\d+(?:\.\d+)?)\s*dB(?:\(A\))?(?:\s|\(|$)/i);
  const noiseLevel = noise?.value.trim().match(/^(하|중|상|낮음|보통|높음)$/)?.[1];
  const noiseValue = noiseDb ? Number(noiseDb[1]) : noiseLevel ? ({하:1,낮음:1,중:2,보통:2,상:3,높음:3} as Record<string,number>)[noiseLevel] : null;
  return <div className="clicker-metrics"><div><span>작동 하중</span>{pressureValue!==null&&Number.isFinite(pressureValue)?<><meter min="0" max={Math.max(100,pressureValue)} value={pressureValue} aria-label={`작동 하중 ${pressureValue}g`}/><strong>{pressureValue}g</strong></>:<span className="muted">실측 자료 등록 전</span>}</div><div><span>소음</span>{noiseValue!==null&&Number.isFinite(noiseValue)?<><meter min="0" max={noiseDb?Math.max(120,noiseValue):3} value={noiseValue} aria-label={`소음 ${noise?.value}`}/><strong>{noiseDb?`${noiseValue}dB`:noiseLevel}</strong></>:<span className="muted">측정 자료 등록 전</span>}</div>{(pressureValue!==null||noiseValue!==null)&&<p>상품 자료 기준입니다. 측정 조건은 상품정보에서 확인해 주세요.</p>}</div>;
}

function OptionSheet({ product, buy, onClose, onAdd }: { product: Product; buy: boolean; onClose: () => void; onAdd: (line: Line) => void }) {
  const [variantId, setVariantId] = useState(product.variants.length === 1 && product.variants[0].stock > 0 ? product.variants[0].id : ""); const [quantity,setQuantity] = useState(1); const variant = product.variants.find(item => item.id === variantId);
  return <Modal title="옵션 선택" onClose={onClose} sheet><div className="sheet-product"><img src={product.images[0]} width="64" height="64" alt=""/><div><strong>{product.name}</strong><p>{money(product.price)}</p></div></div><label className="field">옵션<select value={variantId} onChange={e => { setVariantId(e.target.value); setQuantity(1); }}><option value="">옵션을 선택해 주세요</option>{product.variants.map(item => <option key={item.id} value={item.id} disabled={item.stock <= 0}>{item.label}{item.priceDelta ? ` (+${money(item.priceDelta)})` : ""}{!item.stock ? " · 품절" : ""}</option>)}</select></label>{variant && <div className="option-quantity"><span>수량<small>1회 구매 가능 {Math.min(10,variant.stock)}개</small></span><div className="quantity"><button disabled={quantity <= 1} onClick={() => setQuantity(quantity-1)} aria-label="수량 줄이기"><Icon name="minus" size={15}/></button><span>{quantity}</span><button disabled={quantity >= Math.min(10,variant.stock)} onClick={() => setQuantity(quantity+1)} aria-label="수량 늘리기"><Icon name="plus" size={15}/></button></div></div>}<div className="total-line"><span>상품 합계</span><strong>{money(variant ? (product.price+variant.priceDelta)*quantity : 0)}</strong></div><button className="primary full" disabled={!variant || variant.stock < quantity || quantity > 10} onClick={() => variant && onAdd({ variantId: variant.id, quantity })}>{buy ? "주문서로 이동" : "장바구니에 담기"}</button>{product.sample && <p className="hint">샘플 상품은 체험 주문만 가능합니다.</p>}</Modal>;
}

function Cart({ catalog, cart, setCart, checkout }: { catalog: CatalogResponse; cart: Line[]; setCart: (lines: Line[]) => void; checkout: () => void }) {
  const entries = cart.map(line => { const product = catalog.products.find(item => item.variants.some(variant => variant.id === line.variantId)); const variant = product?.variants.find(item => item.id === line.variantId); return { line, product, variant }; });
  const total = entries.reduce((sum, entry) => sum+(entry.product && entry.variant ? (entry.product.price+entry.variant.priceDelta)*entry.line.quantity : 0),0); const invalid = entries.some(entry => !entry.variant || !entry.product || entry.line.quantity > entry.variant.stock || entry.line.quantity > 10 || !isOpen(entry.product)); const shipping = total >= catalog.settings.shipping.freeThreshold || !total ? 0 : catalog.settings.shipping.fee;
  return <><PageTitle title="장바구니" subtitle="작은 취향들을 한곳에."/>{!cart.length ? <Empty title="장바구니가 비어 있습니다."/> : <div className="two-column"><div className="cart-items">{entries.map(({line,product,variant}) => <article className="cart-item" key={line.variantId}>{product && <Link href={`/product/${product.slug}`}><img src={product.images[0]} width="100" height="100" alt={product.name}/></Link>}<div className="cart-item-copy"><strong>{product?.name ?? "삭제된 상품"}</strong><p>{variant?.label}</p><strong>{money((product?.price ?? 0)+(variant?.priceDelta ?? 0))}</strong><div className="quantity"><button aria-label="수량 줄이기" disabled={line.quantity<=1} onClick={() => setCart(cart.map(item => item.variantId === line.variantId ? {...item,quantity:item.quantity-1} : item))}><Icon name="minus" size={15}/></button><span>{line.quantity}</span><button aria-label="수량 늘리기" disabled={!variant || line.quantity>=Math.min(10,variant.stock)} onClick={() => setCart(cart.map(item => item.variantId === line.variantId ? {...item,quantity:item.quantity+1} : item))}><Icon name="plus" size={15}/></button></div>{(!variant || line.quantity > variant.stock || line.quantity > 10) && <p className="error-text">재고 또는 1회 구매 가능 수량(최대 10개)을 확인해 주세요. 수량을 변경하거나 삭제해 주세요.</p>}</div><button className="icon-button" aria-label={`${product?.name ?? "상품"} 삭제`} onClick={() => setCart(cart.filter(item => item.variantId !== line.variantId))}><Icon name="close" size={18}/></button></article>)}</div><aside className="order-summary"><h2>주문 금액</h2><div><span>상품 금액</span><strong>{money(total)}</strong></div><div><span>배송비</span><span>{money(shipping)}</span></div><p className="hint">초기 버전은 전국 동일 배송비를 적용합니다. 쿠폰은 주문서에서 최종 확인합니다.</p><div className="total-line"><span>예상 결제 금액</span><strong>{money(total+shipping)}</strong></div><button className="primary full" disabled={invalid} onClick={checkout}>{cart.reduce((sum,line) => sum+line.quantity,0)}개 상품 주문하기</button></aside></div>}</>;
}

const blankCustomer: Customer = {name:"",phone:"",email:"",postcode:"",address:"",addressDetail:"",note:""};
const demoCustomer: Customer = {name:"체험 고객",phone:"01000000000",email:"preview@example.com",postcode:"06236",address:"서울특별시 강남구 테헤란로 123",addressDetail:"체험 배송지 (실제 배송 없음)",note:"체험 주문"};
declare global { interface Window { daum?: { Postcode: new(options:{oncomplete:(data:{zonecode:string;roadAddress:string;jibunAddress:string})=>void})=>{open:()=>void} }; } }

function Checkout({ catalog, fallback, onCreated }: { catalog: CatalogResponse; fallback: Line[]; onCreated: () => void }) {
  const router = useRouter(); const [lines,setLines] = useState<Line[]>([]); const [customer,setCustomer] = useState<Customer>(blankCustomer); const [method,setMethod] = useState<PaymentMethod>("CARD"); const [terms,setTerms] = useState(false); const [privacy,setPrivacy] = useState(false); const [coupon,setCoupon] = useState(""); const [busy,setBusy] = useState(false); const [error,setError] = useState(""); const [placed,setPlaced] = useState<{order:Order;accessToken:string;mode:string;pgClientKey:string|null}|null>(null);
  useEffect(() => { setLines(readLocal("nuri-market-checkout",fallback)); if (catalog.mode === "preview") setCustomer(demoCustomer); }, [catalog.mode,fallback]);
  const subtotal = lines.reduce((sum,line) => { const product = catalog.products.find(item => item.variants.some(variant => variant.id === line.variantId)); const variant = product?.variants.find(item => item.id === line.variantId); return sum + (product && variant ? (product.price+variant.priceDelta)*line.quantity : 0); },0); const shipping = subtotal >= catalog.settings.shipping.freeThreshold ? 0 : catalog.settings.shipping.fee;
  async function addressSearch() { setError(""); try { if (!window.daum) await new Promise<void>((resolve,reject) => { const script = document.createElement("script"); script.src="https://t1.daumcdn.net/mapjsapi/bundle/postcode/prod/postcode.v2.js"; script.onload=()=>resolve(); script.onerror=()=>reject(new Error("주소 검색을 불러오지 못했습니다. 주소를 직접 입력해 주세요.")); document.head.appendChild(script); }); window.daum?.Postcode && new window.daum.Postcode({oncomplete:data=>setCustomer(previous=>({...previous,postcode:data.zonecode,address:data.roadAddress||data.jibunAddress}))}).open(); } catch(e) { setError((e as Error).message); } }
  async function place(event: React.FormEvent) {
    event.preventDefault(); setBusy(true); setError("");
    try {
      const body = { lines, customer, method, couponCode: coupon, consent: { terms, privacy, marketing: false, version: "2026-10-07" } };
      const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(JSON.stringify(body)));
      const fingerprint = Array.from(new Uint8Array(digest), value => value.toString(16).padStart(2,"0")).join("");
      let previous: { requestId: string; checkoutToken: string; fingerprint: string } | null = null;
      try { previous = JSON.parse(sessionStorage.getItem("nuri-market-checkout-request") ?? "null"); } catch { /* A prior draft can be replaced. */ }
      const draft = previous?.fingerprint === fingerprint ? previous : { requestId: crypto.randomUUID(), checkoutToken: crypto.randomUUID()+crypto.randomUUID(), fingerprint };
      sessionStorage.setItem("nuri-market-checkout-request",JSON.stringify(draft));
      const result = await request<{order:Order;accessToken:string;mode:string;pgClientKey:string|null}>("/api/orders",{requestId:draft.requestId,checkoutToken:draft.checkoutToken,...body});
      const access = readLocal<Record<string,string>>(ACCESS,{}); access[result.order.id] = result.accessToken; localStorage.setItem(ACCESS,JSON.stringify(access)); sessionStorage.removeItem("nuri-market-checkout-request"); setPlaced(result); onCreated();
    } catch(e) { setError((e as Error).message); } finally { setBusy(false); }
  }
  async function demoPay() { if (!placed) return; setBusy(true); setError(""); try { await request("/api/payments/demo",{orderId:placed.order.id,status:method === "VIRTUAL_ACCOUNT" ? "WAITING_FOR_DEPOSIT" : "PAID"},placed.accessToken); router.push(`/order/${placed.order.id}`); } catch(e) { setError((e as Error).message); setBusy(false); } }
  if (placed) return <><PageTitle title={placed.mode === "preview" ? "체험 주문 확인" : "결제하기"}/><div className="checkout-complete"><Icon name="shield" size={44}/><h2>{money(placed.order.total)}</h2><p>주문번호 {placed.order.number}</p>{placed.mode === "preview" ? <><p className="sample-note">실제 결제·배송이 발생하지 않는 체험 주문입니다.</p><button className="primary full" disabled={busy} onClick={demoPay}>{busy ? "처리 중" : method === "VIRTUAL_ACCOUNT" ? "체험 입금 대기 화면 보기" : "체험 결제 완료 화면 보기"}</button></> : <Payment order={placed.order} token={placed.accessToken} clientKey={placed.pgClientKey}/>}<Link href={`/order/${placed.order.id}`} className="text-button">주문 조회</Link>{error && <p className="error-text" role="alert">{error}</p>}</div></>;
  return <><PageTitle title="주문·결제" subtitle="배송지부터 결제까지, 한 번에."/>{!lines.length ? <Empty title="주문할 상품을 선택해 주세요."/> : <form onSubmit={place} className="two-column checkout-form"><div><section className="form-section"><h2>배송지</h2>{catalog.mode === "preview" && <p className="sample-note">체험용 배송지가 입력되어 있습니다. 실제 개인정보를 입력하지 않아도 됩니다.</p>}<div className="field-grid"><label className="field">받는 분<input autoComplete="name" required maxLength={50} value={customer.name} onChange={e=>setCustomer({...customer,name:e.target.value})}/></label><label className="field">휴대폰<input autoComplete="tel" type="tel" required maxLength={20} value={customer.phone} onChange={e=>setCustomer({...customer,phone:e.target.value})}/></label></div><label className="field">이메일<input type="email" autoComplete="email" required value={customer.email} onChange={e=>setCustomer({...customer,email:e.target.value})}/></label><div className="postcode-row"><label className="field">우편번호<input autoComplete="postal-code" required pattern="[0-9]{5}" value={customer.postcode} onChange={e=>setCustomer({...customer,postcode:e.target.value})}/></label><button type="button" className="secondary" onClick={addressSearch}>주소 찾기</button></div><label className="field">주소<input autoComplete="address-line1" required maxLength={200} value={customer.address} onChange={e=>setCustomer({...customer,address:e.target.value})}/></label><label className="field">상세 주소<input autoComplete="address-line2" maxLength={100} value={customer.addressDetail} onChange={e=>setCustomer({...customer,addressDetail:e.target.value})}/></label><label className="field">배송 요청사항<input maxLength={100} placeholder="배송 요청사항 (선택)" value={customer.note} onChange={e=>setCustomer({...customer,note:e.target.value})}/></label></section><section className="form-section"><h2>주문 상품</h2>{lines.map(line=>{const product=catalog.products.find(item=>item.variants.some(variant=>variant.id===line.variantId));const variant=product?.variants.find(item=>item.id===line.variantId);return <div key={line.variantId} className="checkout-item"><img src={product?.images[0]} alt="" width="68" height="68"/><div><strong>{product?.name ?? "상품 확인 필요"}</strong><p>{variant?.label} / {line.quantity}개</p></div><strong>{money(((product?.price??0)+(variant?.priceDelta??0))*line.quantity)}</strong></div>;})}</section><section className="form-section"><h2>할인</h2><label className="field">쿠폰 코드<input value={coupon} onChange={e=>setCoupon(e.target.value.toUpperCase())} placeholder="보유한 쿠폰 코드 입력" maxLength={30}/></label><p className="hint">서버에서 쿠폰 유효성과 할인 금액을 확인한 뒤 최종 금액을 표시합니다.</p></section><section className="form-section"><h2>결제 수단</h2><div className="payment-options">{([{id:"CARD",label:"신용·체크카드"},{id:"NAVERPAY",label:"네이버페이"},{id:"KAKAOPAY",label:"카카오페이"},{id:"VIRTUAL_ACCOUNT",label:"가상계좌"}] as {id:PaymentMethod;label:string}[]).map(item=><label key={item.id} className={method===item.id ? "selected" : ""}><input type="radio" name="method" value={item.id} checked={method===item.id} onChange={()=>setMethod(item.id)}/>{item.label}</label>)}</div>{method==="VIRTUAL_ACCOUNT" && <p className="hint">계좌 발급은 결제 절차에서 진행됩니다. 입금 기한과 금액은 주문 조회 화면에서 확인해 주세요.</p>}</section></div><aside className="order-summary"><h2>결제 금액 확인</h2><div><span>상품 금액</span><strong>{money(subtotal)}</strong></div><div><span>기본 배송비</span><span>{money(shipping)}</span></div><p className="hint">초기 버전은 전국 동일 배송비를 적용합니다. 할인은 최종 주문 금액에서 확인합니다.</p><div className="total-line"><span>할인 전 예상 금액</span><strong>{money(subtotal+shipping)}</strong></div><div className="consents"><label className="check-label"><input type="checkbox" required checked={terms} onChange={e=>setTerms(e.target.checked)}/><span>[필수] <Link href="/policy/terms" target="_blank">이용약관</Link> 및 주문 내용 확인</span></label><label className="check-label"><input type="checkbox" required checked={privacy} onChange={e=>setPrivacy(e.target.checked)}/><span>[필수] 주문·배송을 위한 <Link href="/policy/privacy" target="_blank">개인정보 처리 안내</Link> 확인</span></label></div>{error && <p className="error-text" role="alert">{error}</p>}<button className="primary full" type="submit" disabled={busy||!terms||!privacy}>{busy ? "주문 확인 중" : catalog.mode === "preview" ? "체험 주문 금액 확인" : "최종 금액 확인하고 결제"}</button><p className="hint">결제 전 서버에서 가격과 재고를 다시 확인합니다.</p></aside></form>}</>;
}

function My() {
  const router=useRouter();const [orders,setOrders]=useState<{id:string;order?:Order;error?:string}[]>([]);const [id,setId]=useState("");const [token,setToken]=useState("");const [error,setError]=useState("");const [busy,setBusy]=useState(false);const [loading,setLoading]=useState(true);
  useEffect(()=>{
    let active=true;
    const recent=Object.entries(readLocal<Record<string,string>>(ACCESS,{})).slice(-20).reverse();
    void Promise.all(recent.map(async ([id,access])=>{
      try {const response=await request<{order:Order}>(`/api/orders?id=${encodeURIComponent(id)}`,undefined,access);return {id,order:response.order};}
      catch(e){return {id,error:(e as Error).message};}
    })).then(results=>{if(active)setOrders(results);}).finally(()=>{if(active)setLoading(false);});
    return ()=>{active=false;};
  },[]);
  async function lookup(event:React.FormEvent){event.preventDefault();setBusy(true);setError("");try{const result=await request<{order:Order}>(`/api/orders?id=${encodeURIComponent(id.trim())}`,undefined,token.trim());const access=readLocal<Record<string,string>>(ACCESS,{});access[result.order.id]=token.trim();localStorage.setItem(ACCESS,JSON.stringify(access));router.push(`/order/${result.order.id}`);}catch(e){setError((e as Error).message);setBusy(false);}}
  return <><PageTitle title="마이페이지" subtitle="주문부터 배송까지, 여기에서 확인하세요."/><div className="two-column"><section className="form-section"><h2>이 브라우저의 주문</h2><p className="hint">최근 20건을 확인합니다. 브라우저에는 주문 접근키만 저장합니다. 공용 기기에서는 주문 기록을 지워 주세요.</p>{loading ? <p className="muted" role="status">주문 정보를 확인하고 있습니다.</p> : orders.length ? <div className="saved-orders">{orders.map(entry=>entry.order ? <Link key={entry.id} href={`/order/${entry.id}`}><Icon name="box"/><div className="saved-order-copy"><strong>{entry.order.number}</strong><span>{paymentLabels[entry.order.paymentStatus]} / {fulfillmentLabels[entry.order.fulfillmentStatus]}</span><b>{money(entry.order.total)}</b></div><Icon name="arrow" size={17}/></Link> : <div key={entry.id} className="saved-order-error"><p>주문 정보를 확인하지 못했습니다.</p><p className="hint">{entry.error}</p><button type="button" className="text-button" onClick={()=>setId(entry.id)}>이 주문의 접근키 다시 입력</button></div>)}</div> : <p className="muted">이 브라우저에 저장된 주문이 없습니다.</p>}{orders.length>0 && <button className="text-button" onClick={()=>{localStorage.removeItem(ACCESS);setOrders([]);}}>이 브라우저의 주문 기록 지우기</button>}</section><form className="form-section" onSubmit={lookup}><h2>다른 기기의 주문 조회</h2><p className="muted">주문 시 안내된 주문번호와 접근키를 입력해 주세요.</p><label className="field">주문번호 (또는 주문 식별자)<input required value={id} onChange={e=>setId(e.target.value)} autoComplete="off"/></label><label className="field">주문 접근키<input type="password" required value={token} onChange={e=>setToken(e.target.value)} autoComplete="off"/></label>{error && <p className="error-text" role="alert">{error}</p>}<button className="primary" disabled={busy}>{busy ? "조회 중" : "주문 조회"}</button></form></div></>;
}

function OrderView({id}:{id:string}) {
  const [order,setOrder]=useState<Order|null>(null);const [error,setError]=useState("");const [busy,setBusy]=useState(false);const [action,setAction]=useState<"claim"|"review"|"inquiry"|null>(null);const [reason,setReason]=useState("");const [type,setType]=useState("CANCEL");const [itemId,setItemId]=useState("");const [rating,setRating]=useState(5);const [claimQuantity,setClaimQuantity]=useState(1);const [message,setMessage]=useState("");
  function token(){return readLocal<Record<string,string>>(ACCESS,{})[id];}
  const [inquiries,setInquiries] = useState<Inquiry[]>([]);
  const [reviews,setReviews] = useState<Review[]>([]);
  async function load(){try{const access=token();if(!access)throw new Error("이 브라우저에 주문 접근키가 없습니다. 마이페이지에서 주문을 조회해 주세요.");const response=await request<{order:Order;inquiries?:Inquiry[];reviews?:Review[]}>(`/api/orders?id=${encodeURIComponent(id)}`,undefined,access);setOrder(response.order);setInquiries(response.inquiries??response.order.inquiries??[]);setReviews(response.reviews??response.order.reviews??[]);setError("");}catch(e){setError((e as Error).message);}}
  useEffect(()=>{void load();},[id]);
  async function submit(event?:React.FormEvent,confirm=false){event?.preventDefault();if(!order)return;setBusy(true);setError("");try{const item=order.items.find(item=>item.id===itemId)??order.items[0];await request("/api/orders",confirm?{action:"confirm",orderId:id}:action==="claim"?{action,orderId:id,type,reason,items:[{itemId:item.id,quantity:claimQuantity}]}:action==="review"?{action,orderId:id,productId:item.productId,rating,content:reason}:{action:"inquiry",orderId:id,subject:"주문 문의",content:reason},token());setAction(null);setReason("");setMessage(confirm?"구매확정을 접수했습니다.":"요청을 접수했습니다.");await load();}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
  async function demoDeposit(){setBusy(true);try{await request("/api/payments/demo",{orderId:id,status:"PAID"},token());await load();}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
  return <><PageTitle title="주문 조회"/>{error && <p className="error-text" role="alert">{error}</p>}{!order ? <Link href="/my" className="secondary inline-button">주문 조회로 이동</Link> : <><div className="order-status"><div><Icon name="box" size={35}/><div><h2>{paymentLabels[order.paymentStatus]}</h2><p>{fulfillmentLabels[order.fulfillmentStatus]}{order.purchaseStatus==="CONFIRMED"?" / 구매확정":""}</p></div></div><span>{order.number}</span></div>{order.isDemo && <div className="sample-note">체험 주문입니다. 실제 결제, 계좌 발급, 배송, 환불은 발생하지 않습니다.</div>}{order.paymentStatus==="WAITING_FOR_DEPOSIT" && <section className="form-section"><h2>입금 대기</h2>{order.virtualAccount ? <p>{order.virtualAccount.bank} {order.virtualAccount.accountNumber}<br/>입금액 {money(order.total)}<br/>기한 {new Date(order.virtualAccount.dueDate).toLocaleString("ko-KR")}</p> : <p>계좌 정보는 결제사에서 발급한 결과를 확인합니다.</p>}{order.isDemo && <button className="secondary" onClick={demoDeposit} disabled={busy}>체험 입금 확인</button>}</section>}<div className="two-column"><div><section className="form-section"><h2>주문 상품</h2>{order.items.map(item=><div key={item.id} className="order-item"><div><strong>{item.name}</strong><p>{item.variantLabel} / {item.quantity}개{item.refundedQty>0?` / 환불 ${item.refundedQty}개`:""}</p></div><strong>{money(item.total)}</strong></div>)}</section><section className="form-section"><h2>배송 정보</h2><p>{order.customer.name} / {order.customer.phone}</p><p>({order.customer.postcode}) {order.customer.address}<br/>{order.customer.addressDetail}</p>{order.shipments.map(shipment=><div className="shipment-info" key={shipment.id}><strong>{shipment.carrier} {shipment.trackingNumber}</strong><span>{shipment.status==="LABEL_REGISTERED"?"송장 등록 (인수 전)":shipment.status==="SHIPPED"?"배송중":"배송 완료"}</span>{shipment.shippedAt&&<small>발송 확인 {new Date(shipment.shippedAt).toLocaleString("ko-KR",{timeZone:"Asia/Seoul"})}</small>}{shipment.deliveredAt&&<small>배달 완료 {new Date(shipment.deliveredAt).toLocaleString("ko-KR",{timeZone:"Asia/Seoul"})}</small>}</div>)}</section>{order.claims.length>0 && <section className="form-section"><h2>요청 내역</h2>{order.claims.map(claim=><div key={claim.id} className="order-item"><div><strong>{claim.type==="CANCEL"?"취소":claim.type==="RETURN"?"반품":"교환"} 요청</strong><p>{claim.reason}</p>{claim.resolution && <p>{claim.resolution}</p>}</div><span>{({REQUESTED:"접수",APPROVED:"승인",REJECTED:"반려",COMPLETED:"처리 완료"})[claim.status]}</span></div>)}</section>}{inquiries.length>0 && <section className="form-section"><h2>주문 문의</h2>{inquiries.map(inquiry=><div key={inquiry.id} className="moderation-item"><div><strong>{inquiry.subject}</strong><p>{inquiry.content}</p>{inquiry.reply ? <><span className="tag blue">답변완료</span><p className="reply">{inquiry.reply}</p>{inquiry.repliedAt&&<small>답변일 {new Date(inquiry.repliedAt).toLocaleString("ko-KR",{timeZone:"Asia/Seoul"})}</small>}</> : <span className="tag">답변 대기</span>}</div></div>)}</section>}{reviews.length>0 && <section className="form-section"><h2>내가 작성한 리뷰</h2>{reviews.map(review=><div key={review.id} className="moderation-item"><div><strong>{review.rating}점</strong><p>{review.content}</p><span className="tag">{review.status==="PENDING"?"검수 대기":review.status==="APPROVED"?"승인":"반려"}</span></div></div>)}</section>}</div><aside className="order-summary"><h2>결제 내역</h2><div><span>상품 금액</span><strong>{money(order.subtotal)}</strong></div><div><span>할인</span><span>-{money(order.discount)}</span></div><div><span>배송비</span><span>{money(order.shipping)}</span></div><div className="total-line"><span>주문 금액</span><strong>{money(order.total)}</strong></div>{order.refundTotal>0 && <div><span>환불 금액</span><strong>{money(order.refundTotal)}</strong></div>}<div className="order-actions"><button className="secondary" onClick={()=>{setAction("claim");setItemId(order.items[0]?.id??"");setClaimQuantity(1);}}>취소·교환·반품 요청</button>{order.fulfillmentStatus==="DELIVERED" && order.purchaseStatus!=="CONFIRMED" && <button className="primary" disabled={busy} onClick={()=>void submit(undefined,true)}>구매확정</button>}<button className="secondary" disabled={order.fulfillmentStatus!=="DELIVERED"||!order.items.some(item=>item.quantity>item.refundedQty)} onClick={()=>{setAction("review");setItemId(order.items.find(item=>item.quantity>item.refundedQty)?.id??"");}}>구매 상품 리뷰</button><button className="secondary" onClick={()=>setAction("inquiry")}>주문 문의</button></div><p className="hint">구매확정 이후에도 표시·광고 또는 계약과 다른 상품의 청약철회 및 하자 문의를 접수할 수 있습니다.</p><details><summary>다른 기기에서 조회할 접근키</summary><p>접근키를 타인에게 공유하지 마세요.</p><code className="access-key">{token()}</code><p className="hint">주문 식별자: {order.id}</p></details></aside></div>{message && <p className="success-text" role="status">{message}</p>}{action && <Modal title={action==="claim"?"취소·교환·반품 요청":action==="review"?"리뷰 작성":"주문 문의"} onClose={()=>setAction(null)}><form onSubmit={submit}>{action==="claim" && <label className="field">요청 유형<select value={type} onChange={e=>setType(e.target.value)}><option value="CANCEL">취소</option><option value="RETURN">반품</option><option value="EXCHANGE">교환</option></select></label>}{action!=="inquiry" && <label className="field">상품<select value={itemId} onChange={e=>setItemId(e.target.value)}>{order.items.filter(item=>action!=="review"||item.quantity>item.refundedQty).map(item=><option key={item.id} value={item.id}>{item.name} / {item.variantLabel}</option>)}</select></label>}{action==="review" && <label className="field">별점<select value={rating} onChange={e=>setRating(Number(e.target.value))}>{[5,4,3,2,1].map(value=><option key={value} value={value}>{value}점</option>)}</select></label>}{action==="claim" && <label className="field">요청 수량<input type="number" required min="1" step="1" max={(order.items.find(item=>item.id===itemId)?.quantity??0)-(order.items.find(item=>item.id===itemId)?.refundedQty??0)} value={claimQuantity} onChange={e=>setClaimQuantity(Number(e.target.value))}/></label>}<label className="field">{action==="claim"?"요청 사유":"내용"}<textarea required minLength={5} maxLength={2000} rows={5} value={reason} onChange={e=>setReason(e.target.value)} placeholder="5자 이상 입력해 주세요"/></label>{action==="claim" && <p className="hint">선택한 상품과 수량에 대해 요청합니다. 구매확정 이후의 하자·계약 불일치도 접수할 수 있습니다.</p>}<button className="primary full" disabled={busy}>{busy?"접수 중":"접수하기"}</button>{error && <p className="error-text" role="alert">{error}</p>}</form></Modal>}</>}</>;
}

function Footer({catalog}:{catalog:CatalogResponse}) { const seller=catalog.settings.seller;return <footer className="footer"><div className="footer-top"><Link href="/" className="wordmark"><img src="/brand/nuri-market-light.svg" alt="NURI MARKET" width="7906" height="1120"/></Link><nav aria-label="정책 및 운영 메뉴"><Link href="/policy/terms">이용약관</Link><Link href="/policy/privacy">개인정보처리방침</Link><Link href="/policy/shipping">배송·교환·반품</Link><Link href="/nurimarket/admin">관리자</Link></nav></div><div className="seller-info"><span>상호 {seller.company||"확정 전"}</span><span>대표 {seller.representative||"확정 전"}</span><span>사업자등록번호 {seller.businessNumber||"확정 전"}</span><span>통신판매업신고번호 {seller.commerceNumber||"등록 확인 중"}</span><span>주소 {seller.address||"확정 전"}</span><span>고객센터 {seller.phone||"연락처 등록 전"}{seller.email?` / ${seller.email}`:""}</span><span>호스팅 서비스 {seller.hosting||"선정 전"}</span></div>{seller.escrowUrl && <a className="text-button" href={seller.escrowUrl} target="_blank" rel="noopener noreferrer">구매안전서비스 가입 확인</a>}<p className="copyright">© NURI MARKET. {catalog.mode!=="live"?"출시 준비 중인 체험 스토어입니다.":""}</p></footer>; }
function Policy({kind,catalog}:{kind:string;catalog:CatalogResponse}) { const seller=catalog.settings.seller;const shipping=catalog.settings.shipping;const title=kind==="privacy"?"개인정보처리방침":kind==="shipping"?"배송·교환·반품 안내":"이용약관";return <article className="policy"><PageTitle title={title} subtitle="시행 예정일 2026년 10월 7일 · 출시 전 확정본 검토"/>{!catalog.settings.policiesApproved && <p className="sample-note">출시 전 검토 중인 운영 정책입니다. 미확정 계약·담당자·보관 및 파기 절차는 판매 개시 전에 확정합니다.</p>}{kind==="privacy"?<><h2>개인정보 처리 목적과 항목</h2><p>계약 이행에 필요한 주문 처리, 결제 확인, 배송, 취소·환불 및 고객 상담을 위해 이름, 휴대폰 번호, 이메일, 배송지 주소, 주문·결제 정보를 처리합니다. 해당 처리는 개인정보 보호법 제15조 제1항 제4호 등 적법한 근거를 적용하며, 주문 화면의 안내 확인을 선택 정보의 수집 동의와 구분합니다. 선택적인 배송 요청사항에 불필요한 민감정보를 기재하지 마세요. 회원가입이나 마케팅 동의 없이 비회원 주문을 지원합니다.</p><h2>보유 기간과 파기</h2><p>계약·청약철회 및 대금 결제·재화 공급에 관한 기록은 5년, 소비자 불만·분쟁 처리 기록은 3년, 표시·광고 기록은 6개월 등 법정 보존 기간을 적용합니다. 목적 달성 후 법정 보존 대상은 접근을 제한해 분리 보관하며, 기간 종료 후 복구할 수 없는 방식으로 파기합니다.</p><h2>처리 위탁과 국외 이전</h2><p>결제 처리: 토스페이먼츠(계약 확정 후 적용). 배송·알림 발송·호스팅·데이터 저장 업체, 실제 저장 위치와 국외 이전 해당 여부는 확정 계약을 기준으로 공개하고 법적 요건을 충족합니다. 운영 업체가 확정되지 않은 상태에서 실제 주문 정보의 외부 전송은 활성화하지 않습니다.</p><h2>권리 행사와 보호 조치</h2><p>정보 열람·정정·삭제·처리정지 요청은 고객센터로 접수할 수 있습니다. 법정 보존 정보는 보존 의무를 함께 안내합니다. 주문 접근키, 관리자 권한, 기록 접근 통제와 감사 기록을 적용합니다. 아동 대상 상품 판매와 만 14세 미만 이용자의 개인정보 처리는 구분하며 필요한 동의 절차 확정 전에는 해당 회원 기능을 제공하지 않습니다.</p><h2>개인정보 문의</h2><p>개인정보 보호책임자: 출시 전 지정<br/>이메일: {seller.email||"확정 전"}<br/>연락처: {seller.phone||"확정 전"}</p></>:kind==="shipping"?<><h2>배송</h2><p>기본 배송비 {money(shipping.fee)}, {money(shipping.freeThreshold)} 이상 무료입니다. 초기 버전은 전국 동일 배송비를 적용하며 도서산간 추가 요금 계산은 제공하지 않습니다. 실제 출고 일정·계약 택배사·배송 지역은 상품 출시 전 확정합니다. 송장 등록 상태와 실제 택배사 인수 상태를 구분해 안내합니다.</p><h2>청약철회</h2><p>일반적으로 계약 내용을 받은 날부터 7일 이내 청약철회할 수 있으며, 상품 공급이 더 늦은 경우 공급받거나 공급이 시작된 날부터 7일 이내 신청할 수 있습니다. 상품이 표시·광고 또는 계약 내용과 다르면 공급받은 날부터 3개월 이내, 그 사실을 알았거나 알 수 있었던 날부터 30일 이내 청약철회할 수 있습니다.</p><p>단순 개봉만으로 모든 청약철회를 제한하지 않습니다. 사용으로 가치가 현저히 감소한 경우 등 법정 제한 사유가 적용될 때에는 상품별로 구매 전에 안내하며, 내용 확인을 위한 포장 훼손은 해당 사유와 구분합니다. 구매확정 버튼이나 자동 구매확정만으로 법적 권리가 사라지지 않습니다.</p><h2>비용과 환급</h2><p>단순 변심 반환 비용은 구매자 부담이며 상품 하자·오배송 등 판매자 귀책이면 판매자가 부담합니다. 반환 상품을 수령한 후 법정 기한에 맞춰 환급 절차를 진행합니다. 쿠폰·번들·무료배송 조건이 변경되는 일부 취소는 최종 환급액의 계산 근거를 안내합니다.</p><p>반품 접수 주소: {shipping.returnAddress||"출시 전 확정"}<br/>기본 반품비: {money(shipping.returnFee)} (지역·수거 형태에 따른 실제 비용은 요청 처리 전 안내)</p><h2>요청 방법</h2><p>마이페이지의 주문 조회에서 취소·교환·반품 요청을 접수할 수 있습니다. 구매확정 이후의 하자·계약 불일치 문의도 고객센터에서 접수합니다.</p></>:<><h2>판매자와 이용 범위</h2><p>이 스토어는 {seller.company||"판매자 정보 확정 전"}에서 운영하는 자사 브랜드 상품 판매몰입니다. 현재 샘플 상품은 실제 구매·배송 없이 기능을 체험하는 용도로 제공됩니다.</p><h2>주문과 계약</h2><p>상품의 옵션·수량·가격·배송비를 확인한 뒤 주문할 수 있습니다. 서버에서 최종 가격과 재고를 확인하며 결제 상태와 주문 접수 결과를 안내합니다. 재고 부족, 안전 요건 미충족 등의 사유로 판매할 수 없으면 알리고 결제 취소·환급 절차를 진행합니다.</p><h2>미성년자의 계약</h2><p>미성년자가 법정대리인의 동의 없이 계약한 경우 본인 또는 법정대리인이 계약을 취소할 수 있습니다. 관련 요청은 주문 조회의 취소·반품 요청 또는 고객센터에서 접수합니다.</p><h2>결제와 가상계좌</h2><p>제공되는 수단은 카드, 간편결제와 가상계좌로 결제사 계약 및 심사 결과에 따라 확정됩니다. 가상계좌 주문은 안내된 기한 내 정확한 금액을 입금해야 합니다. 중복 입금·입금 취소·만료와 입금 충돌은 결제사 기록을 대사하여 처리합니다.</p><h2>배송·취소·교환·반품</h2><p>자세한 기준은 배송·교환·반품 정책과 상품별 고지를 적용합니다. 약관, 상품별 고지 또는 구매확정 처리로 소비자의 법정 권리를 배제하지 않습니다. 포장·출고 작업이 진행 중이면 즉시 취소 대신 요청 접수 후 실제 출고 상태를 확인합니다.</p><h2>후기와 콘텐츠</h2><p>후기는 실제 주문 상품을 대상으로 작성하며 개인정보 노출·권리 침해·무관한 내용을 기준으로 검수합니다. 낮은 평점 자체를 삭제 사유로 삼지 않습니다. 후기 보상이 제공되는 경우 보상 조건과 사실을 명확히 표시합니다.</p><h2>분쟁과 문의</h2><p>문의: {seller.email||"이메일 확정 전"} / {seller.phone||"연락처 확정 전"}<br/>이 약관에 정하지 않은 사항은 관련 법령을 따릅니다. 변경 약관은 적용일과 변경 내용을 사전에 안내합니다.</p></>}</article>; }
